select left(stem,110) from questions q join subject_groups g on g.id=q.subject_group_id where g.code='statistics' and (stem ilike '%Laspeyres%' or stem ilike '%tossed%' or stem ilike '%sum of 7%' or stem ilike '%grams%' or stem ilike '%squared deviations%minimum%' or stem ilike '%y = 4 + 2.5x%' or stem ilike '%Σx²%' or stem ilike '%mode of%' or stem ilike '%index number%' or stem ilike '%price index%');
